<script setup lang="ts">
import {ref, onMounted, onBeforeUnmount} from 'vue';
import {useI18n} from 'vue-i18n';
const {locale}=useI18n();const tx=(z:string,e:string)=>locale.value==='zh'?z:e;
const slides=[
 {image:'/images/vera-interior-hero.png',title:['让光线，\n恰到好处。','Light,\nconsidered.'],lead:['为每一扇窗，找到合适的遮阳。','The right shading for every window.'],alt:['百叶窗调节自然光的室内示意空间','Illustrative interior with venetian blinds and natural light']},
 {image:'/images/hero-room.jpg',title:['光与私密，\n从容平衡。','A balance of light\nand privacy.'],lead:['把空间的感受，放在选型的起点。','Begin with the way you want your space to feel.'],alt:['明亮空间中的白色百叶窗示意','Illustrative white blinds in a bright interior']},
 {image:'/images/vera-timber-detail.png',title:['材质有温度，\n细节有分寸。','Material warmth.\nConsidered detail.'],lead:['从每一片叶片，探索不同的可能。','Explore the possibilities in every slat.'],alt:['木百叶叶片与梯带材质特写示意','Illustrative close-up of timber slats and ladder tape']}
];
const current=ref(0),paused=ref(false),hovered=ref(false),focused=ref(false),reduced=ref(false);
let timer:ReturnType<typeof setInterval>|undefined,media:MediaQueryList|undefined;
function move(n:number){current.value=(current.value+n+slides.length)%slides.length;paused.value=true}
function choose(index:number){current.value=index;paused.value=true}
function focusOut(e:FocusEvent){focused.value=!!e.relatedTarget&&(e.currentTarget as HTMLElement).contains(e.relatedTarget as Node)}
function motion(e:MediaQueryListEvent){reduced.value=e.matches;if(e.matches)paused.value=true}
onMounted(()=>{media=window.matchMedia('(prefers-reduced-motion: reduce)');reduced.value=media.matches;paused.value=media.matches;media.addEventListener('change',motion);timer=setInterval(()=>{if(!paused.value&&!hovered.value&&!focused.value&&!document.hidden)current.value=(current.value+1)%slides.length},8000)});
onBeforeUnmount(()=>{if(timer)clearInterval(timer);media?.removeEventListener('change',motion)});
</script>
<template>
<section class="hero-carousel" :class="{reduced}" role="region" aria-roledescription="carousel" :aria-label="tx('VERA空间与材质展示','VERA spaces and materials')" @mouseenter="hovered=true" @mouseleave="hovered=false" @focusin="focused=true" @focusout="focusOut">
